(function () {
  // Matches PNGs generated by redmine_comment_pdftopng from a PDF attachment:
  // "<base>_a<pdfAttachmentId>_cover.png" or "<base>_a<pdfAttachmentId>_p007.png".
  var PDF_PNG_RE = /^(.+?)_a(\d+)_(?:cover|p(\d+))\.png$/i;

  function pdfPagesLabel(opts, count) {
    return count === 1
      ? opts.i18n.pdfPagesOne
      : (opts.i18n.pdfPagesOther || '').replace('%{count}', String(count));
  }

  function attachmentIdFromHref(href) {
    if (!href) return null;
    var m = /\/attachments\/(\d+)\b/.exec(href);
    return m ? m[1] : null;
  }

  // ---- main ticket-level attachment table (.attachments > table > tr) ----

  function teardown(container) {
    var state = container._jnFileState;
    if (!state) return;

    if (state.summary.parentNode) state.summary.parentNode.removeChild(state.summary);
    if (state.filterInput && state.filterInput.parentNode) state.filterInput.parentNode.removeChild(state.filterInput);
    state.pdfGroups.forEach(teardownPdfGroup);
    container.classList.remove('jn-file-navigator-mode');
    container.hidden = false;
    Array.prototype.slice.call(container.querySelectorAll('tr')).forEach(function (tr) { tr.hidden = false; });
    container._jnFileState = null;
  }

  function buildFilter(container, rows, opts) {
    var input = document.createElement('input');
    input.type = 'search';
    input.className = 'jn-file-filter';
    input.placeholder = opts.filterPlaceholder || '';

    input.addEventListener('input', function () {
      var term = input.value.trim().toLowerCase();
      rows.forEach(function (tr) {
        tr.hidden = term !== '' && tr.textContent.toLowerCase().indexOf(term) === -1;
      });
    });

    container.parentNode.insertBefore(input, container);
    return input;
  }

  function rowAttachmentLink(tr) {
    return tr.querySelector('a.icon-attachment');
  }

  // Groups PNG rows generated from the same source PDF behind one toggle,
  // nested under the original PDF's own row when it's present in the same
  // list, so a PDF with many converted pages doesn't flood the list.
  function groupPdfRows(rows, opts) {
    var groups = {};

    rows.forEach(function (tr) {
      var link = rowAttachmentLink(tr);
      var text = link ? link.textContent.trim() : '';
      var m = PDF_PNG_RE.exec(text);
      if (!m) return;
      var key = (m[1] + '_a' + m[2]).toLowerCase();
      groups[key] = groups[key] || { base: m[1], id: m[2], rows: [] };
      groups[key].rows.push(tr);
    });

    var inserted = [];

    Object.keys(groups).forEach(function (key) {
      var group = groups[key];
      var host = rows.find(function (tr) {
        if (group.rows.indexOf(tr) !== -1) return false;
        var link = rowAttachmentLink(tr);
        if (!link) return false;
        var text = link.textContent.trim();
        if (!/\.pdf$/i.test(text)) return false;
        var idFromHref = attachmentIdFromHref(link.getAttribute('href'));
        if (idFromHref) return idFromHref === group.id;
        return text.replace(/\.pdf$/i, '').toLowerCase() === group.base.toLowerCase();
      });

      var toggle = document.createElement('button');
      toggle.type = 'button';
      toggle.className = 'jn-pdf-group-toggle';
      toggle.textContent = pdfPagesLabel(opts, group.rows.length);
      toggle.setAttribute('aria-expanded', 'false');

      var entry = { toggle: toggle, rows: group.rows, hostCell: null, groupRow: null };

      if (host) {
        var cell = host.querySelector('td');
        if (cell) {
          cell.appendChild(toggle);
          entry.hostCell = cell;
        }
        host.classList.add('jn-pdf-host-row');
        entry.host = host;
      } else {
        var groupRow = document.createElement('tr');
        groupRow.className = 'jn-pdf-group-row';
        var td = document.createElement('td');
        td.colSpan = 4;
        var icon = document.createElement('span');
        icon.className = 'icon icon-attachment jn-pdf-group-icon';
        icon.textContent = opts.i18n.pdfGroupFallback || '';
        td.appendChild(icon);
        td.appendChild(toggle);
        groupRow.appendChild(td);
        group.rows[0].parentNode.insertBefore(groupRow, group.rows[0]);
        entry.groupRow = groupRow;
      }

      group.rows.forEach(function (tr) {
        tr.classList.add('jn-pdf-page-row');
        tr.hidden = true;
      });

      var expanded = false;
      toggle.addEventListener('click', function () {
        expanded = !expanded;
        toggle.setAttribute('aria-expanded', String(expanded));
        toggle.classList.toggle('jn-pdf-group-open', expanded);
        group.rows.forEach(function (tr) { tr.hidden = !expanded; });
      });

      inserted.push(entry);
    });

    return inserted;
  }

  function teardownPdfGroup(entry) {
    if (entry.toggle && entry.toggle.parentNode) entry.toggle.parentNode.removeChild(entry.toggle);
    if (entry.groupRow && entry.groupRow.parentNode) entry.groupRow.parentNode.removeChild(entry.groupRow);
    if (entry.host) entry.host.classList.remove('jn-pdf-host-row');
    entry.rows.forEach(function (row) {
      row.classList.remove('jn-pdf-page-row');
      row.hidden = false;
    });
  }

  function applyOne(container, opts) {
    teardown(container);
    if (!opts.enabled) return;

    var rows = Array.prototype.slice.call(container.querySelectorAll('table tr'));
    if (rows.length === 0) return;

    var summary = document.createElement('button');
    summary.type = 'button';
    summary.className = 'jn-file-summary icon icon-attachment';
    summary.textContent = container.dataset.jnSummary || '';
    summary.setAttribute('aria-expanded', 'false');

    var state = { summary: summary, filterInput: null, pdfGroups: [] };
    var expanded = false;

    summary.addEventListener('click', function () {
      expanded = !expanded;
      container.hidden = !expanded;
      summary.setAttribute('aria-expanded', String(expanded));
      summary.classList.toggle('jn-file-summary-open', expanded);

      if (expanded && opts.navigatorEnabled) {
        container.classList.add('jn-file-navigator-mode');
        if (!state.filterInput && rows.length > 6) {
          state.filterInput = buildFilter(container, rows, opts);
        }
        if (state.filterInput) state.filterInput.hidden = false;
        if (state.pdfGroups.length === 0) {
          state.pdfGroups = groupPdfRows(rows, opts);
        }
      } else {
        container.classList.remove('jn-file-navigator-mode');
        if (state.filterInput) state.filterInput.hidden = true;
      }
    });

    container.parentNode.insertBefore(summary, container);
    container.hidden = true;
    container._jnFileState = state;
  }

  // ---- per-comment attachment list (ul.details li containing a file link) ----

  // Unlike the main attachment table, Redmine's per-journal "Datei X wurde
  // hinzugefügt" detail string links to the attachment with a plain <a> and
  // no distinguishing class, so these have to be matched by href instead.
  function detailsAttachmentLink(li) {
    return li.querySelector('a[href*="/attachments/"]');
  }

  function detailsFileItems(ul) {
    return Array.prototype.filter.call(ul.children, function (li) {
      return li.tagName === 'LI' && detailsAttachmentLink(li);
    });
  }

  function teardownDetailsList(ul) {
    var state = ul._jnCommentFileState;
    if (!state) return;

    if (state.summary.parentNode) state.summary.parentNode.removeChild(state.summary);
    state.pdfGroups.forEach(function (g) {
      if (g.groupRow.parentNode) g.groupRow.parentNode.removeChild(g.groupRow);
      g.rows.forEach(function (li) { li.classList.remove('jn-pdf-page-row'); });
    });
    state.items.forEach(function (li) {
      li.hidden = false;
      li.classList.remove('jn-comment-file-item');
    });
    ul._jnCommentFileState = null;
  }

  function groupPdfListItems(items, opts) {
    var groups = {};

    items.forEach(function (li) {
      var link = detailsAttachmentLink(li);
      var text = link ? link.textContent.trim() : '';
      var m = PDF_PNG_RE.exec(text);
      if (!m) return;
      var key = (m[1] + '_a' + m[2]).toLowerCase();
      groups[key] = groups[key] || { rows: [] };
      groups[key].rows.push(li);
    });

    var result = [];

    Object.keys(groups).forEach(function (key) {
      var group = groups[key];
      if (group.rows.length < 2) return;

      var groupRow = document.createElement('li');
      groupRow.className = 'jn-pdf-group-row jn-comment-file-item';
      groupRow.hidden = true;

      var toggle = document.createElement('button');
      toggle.type = 'button';
      toggle.className = 'jn-pdf-group-toggle';
      toggle.textContent = pdfPagesLabel(opts, group.rows.length);
      toggle.setAttribute('aria-expanded', 'false');
      groupRow.appendChild(toggle);

      group.rows[0].parentNode.insertBefore(groupRow, group.rows[0]);
      group.rows.forEach(function (li) {
        li.classList.add('jn-pdf-page-row');
        li.hidden = true;
      });

      var expanded = false;
      toggle.addEventListener('click', function () {
        expanded = !expanded;
        toggle.setAttribute('aria-expanded', String(expanded));
        toggle.classList.toggle('jn-pdf-group-open', expanded);
        group.rows.forEach(function (li) { li.hidden = !expanded; });
      });

      result.push({ groupRow: groupRow, rows: group.rows });
    });

    return result;
  }

  function applyDetailsList(ul, opts) {
    teardownDetailsList(ul);
    if (!opts.commentFilelistEnabled) return;

    var items = detailsFileItems(ul);
    if (items.length < 2) return;

    var summary = document.createElement('li');
    summary.className = 'jn-comment-files-summary jn-comment-file-item';

    var toggle = document.createElement('button');
    toggle.type = 'button';
    toggle.className = 'jn-comment-files-toggle';
    toggle.textContent = items.length === 1
      ? opts.i18n.commentFilesOne
      : (opts.i18n.commentFilesOther || '').replace('%{count}', String(items.length));
    toggle.setAttribute('aria-expanded', 'false');
    summary.appendChild(toggle);

    ul.insertBefore(summary, items[0]);
    items.forEach(function (li) {
      li.classList.add('jn-comment-file-item');
      li.hidden = true;
    });

    var pdfGroups = groupPdfListItems(items, opts);
    var groupedRows = {};
    pdfGroups.forEach(function (g) { g.rows.forEach(function (li) { groupedRows[Array.prototype.indexOf.call(items, li)] = true; }); });

    var expanded = false;
    toggle.addEventListener('click', function () {
      expanded = !expanded;
      toggle.setAttribute('aria-expanded', String(expanded));
      items.forEach(function (li, idx) {
        if (groupedRows[idx]) return; // stays governed by its own pdf-group toggle
        li.hidden = !expanded;
      });
      pdfGroups.forEach(function (g) { g.groupRow.hidden = !expanded; });
    });

    ul._jnCommentFileState = { summary: summary, items: items, pdfGroups: pdfGroups };
  }

  function apply(rootEl, opts) {
    if (!rootEl) return;

    var containers = Array.prototype.slice.call(rootEl.querySelectorAll('.attachments'));
    containers.forEach(function (container) { applyOne(container, opts); });

    var detailsLists = Array.prototype.slice.call(rootEl.querySelectorAll('ul.details'));
    detailsLists.forEach(function (ul) { applyDetailsList(ul, opts); });
  }

  window.RedmineAttachmentCollapse = { apply: apply };
})();
